-- Fixtures of the automated PDV smokes (H1/H2/D). Runs share one synthetic cohort "smoke-pdv" (first free year from 2001:
-- a cohort's year is unique, so an ephemeral cohort per run would consume real years; the E0 smoke uses 2100 down). The cohort is reactivated at the
-- start of a run and archived at its end; each run brings its own with synthetic people (pre-confirmed, password generated by the job and never printed), a catalog slice,
-- stock, two terminals and a purchase order, all created through the product RPCs by the run's administrator so
-- ledgers, audit and outbox stay coherent. retire() leaves the run inert and is idempotent; retire_stale() retires
-- runs left behind by an interrupted job. No real payment is ever made: Pix and card confirmations are manual.
create schema if not exists smoketest;

create or replace function smoketest.as_user(p_user uuid, p_cohort uuid) returns void language plpgsql as $$
begin
  perform set_config('request.jwt.claim.sub', p_user::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config('request.headers', json_build_object('x-germinatura-cohort', p_cohort)::text, true);
  perform set_config('role', 'authenticated', true);
  perform set_config('germinatura.cohort_scope', '', true);
end;
$$;
create or replace function smoketest.as_system(p_cohort uuid) returns void language plpgsql as $$
begin
  perform set_config('role', 'postgres', true);
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claim.role', '', true);
  perform set_config('request.headers', '', true);
  perform set_config('germinatura.cohort_scope', '', true);
  perform private.enter_cohort_context(p_cohort);
end;
$$;

-- A synthetic, pre-confirmed person that belongs only to the run cohort (the default-cohort membership the signup
-- trigger gives every direct insert is withdrawn, so smoke people never show up in a real cohort).
create or replace function smoketest.person(p_run text, p_tag text, p_password text, p_cohort uuid) returns uuid language plpgsql as $$
declare
  v_id uuid;
  v_email text := 'smoke.' || p_run || '.' || p_tag || '@institutojef.org.br';
  v_default uuid;
begin
  perform smoketest.as_system(null);
  v_default := (select id from public.cohorts where is_default);
  select id into v_id from auth.users where email = v_email;
  if v_id is not null then return v_id; end if;
  v_id := gen_random_uuid();
  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, confirmation_token, recovery_token,
    email_change_token_new, email_change, phone_change_token, email_change_token_current, reauthentication_token,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
  values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf', 6)), now(), '', '', '', '', '', '', '',
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('name', 'Smoke ' || p_tag, 'username', 'smk' || p_run || p_tag), now(), now());
  insert into auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), v_id::text, v_id, jsonb_build_object('sub', v_id, 'email', v_email, 'email_verified', true), 'email', now(), now(), now());
  perform smoketest.as_system(v_default);
  delete from cohort_data.user_roles where user_id = v_id and cohort_id = v_default;
  update public.user_cohorts set status = 'INACTIVE', updated_at = now() where user_id = v_id and cohort_id = v_default;
  perform smoketest.as_system(p_cohort);
  insert into public.user_cohorts (user_id, cohort_id, status) values (v_id, p_cohort, 'ACTIVE')
  on conflict (user_id, cohort_id) do update set status = 'ACTIVE', updated_at = now();
  insert into cohort_data.user_roles (user_id, role_id, cohort_id) select v_id, id, p_cohort from public.roles where key = 'CONSUMIDOR'
  on conflict do nothing;
  return v_id;
end;
$$;

create or replace function smoketest.prepare(p_run text, p_password text) returns jsonb language plpgsql as $$
declare
  v_slug text := 'smoke-pdv';
  v_cohort uuid;
  v_admin uuid;
  v_central uuid;
  v_category uuid;
  v_result jsonb;
  v_products jsonb := '{}';
  v_product uuid;
  v_sellers jsonb := '[]';
  v_seller uuid;
  v_location uuid;
  v_terminals jsonb := '{}';
  v_supplier uuid;
  v_order jsonb;
  v_item record;
begin
  if p_run !~ '^[a-z0-9]{6,12}$' then raise exception 'SMOKE_INVALID_RUN'; end if;
  perform smoketest.as_system(null);
  select id into v_cohort from public.cohorts where slug = v_slug;
  if v_cohort is null then
    -- A cohort's year is unique; the E0 smoke takes 2100 downwards, so this one takes the first free year from 2001 up.
    insert into public.cohorts (name, year, slug, status)
    select 'Smoke PDV (sintética)', candidate.year, v_slug, 'ACTIVE' from generate_series(2001, 2049) as candidate(year)
    where not exists (select 1 from public.cohorts cohort where cohort.year = candidate.year) order by candidate.year limit 1
    returning id into v_cohort;
    if v_cohort is null then raise exception 'SMOKE_NO_FREE_COHORT_YEAR'; end if;
  end if;
  update public.cohorts set status = 'ACTIVE' where id = v_cohort and status <> 'ACTIVE';

  -- Administrator of the run cohort (ADMIN holds catalog, stock, procurement, finance and the acréscimo waiver).
  v_admin := smoketest.person(p_run, 'admin', p_password, v_cohort);
  perform smoketest.as_system(v_cohort);
  perform private.provision_cohort(v_cohort, v_admin);
  perform smoketest.as_system(v_cohort);
  insert into cohort_data.user_roles (user_id, role_id, cohort_id) select v_admin, id, v_cohort from public.roles where key = 'ADMIN'
  on conflict do nothing;
  select id into v_central from cohort_data.stock_locations where cohort_id = v_cohort and location_type = 'CENTRAL' and active;

  perform smoketest.as_user(v_admin, v_cohort);
  v_result := public.save_catalog_category(null, null, 'Smoke ' || p_run, 'smoke-' || p_run, true, 990, 'Smoke automatizado do PDV', 'smoke:' || p_run || ':category', gen_random_uuid());
  v_category := (v_result ->> 'id')::uuid;
  foreach v_result in array array[
    -- A long name on purpose: the phone layout must hold it (it once widened the PDV catalog at 320 px).
    jsonb_build_object('key', 'kinder', 'name', 'Brownie Kinder Recheado com Creme de Avelã ' || p_run, 'price', 2590),
    jsonb_build_object('key', 'ninho', 'name', 'Bolo Ninho ' || p_run, 'price', 1990)] loop
    v_order := public.save_catalog_product(null, null, v_category, 'smoke-' || p_run || '-' || (v_result ->> 'key'), v_result ->> 'name',
      null, true, false, false, false, false, 'Smoke automatizado do PDV', 'smoke:' || p_run || ':product:' || (v_result ->> 'key'), gen_random_uuid());
    v_product := (v_order ->> 'id')::uuid;
    perform public.set_catalog_product_price(v_product, (v_order ->> 'revision')::integer, (v_result ->> 'price')::bigint, 'Preço do smoke',
      'smoke:' || p_run || ':price:' || (v_result ->> 'key'), gen_random_uuid());
    perform public.save_catalog_product(v_product, (select revision from public.products where id = v_product), v_category,
      'smoke-' || p_run || '-' || (v_result ->> 'key'), v_result ->> 'name', null, true, true, true, false, false, 'Publicar para o smoke',
      'smoke:' || p_run || ':publish:' || (v_result ->> 'key'), gen_random_uuid());
    perform public.adjust_stock(v_central, v_product, 200, 'Estoque do smoke', 'smoke:' || p_run || ':stock:' || (v_result ->> 'key'), gen_random_uuid());
    v_products := v_products || jsonb_build_object(v_result ->> 'key', jsonb_build_object('id', v_product, 'name', v_result ->> 'name', 'priceCents', (v_result ->> 'price')::integer));
  end loop;

  -- Two sellers with their own stock.
  for i in 1 .. 2 loop
    v_seller := smoketest.person(p_run, 's' || i, p_password, v_cohort);
    perform smoketest.as_user(v_admin, v_cohort);
    perform public.set_user_access(v_seller, array['CONSUMIDOR', 'VENDEDOR'], true, gen_random_uuid());
    perform smoketest.as_system(v_cohort);
    select id into v_location from cohort_data.stock_locations where seller_id = v_seller and cohort_id = v_cohort;
    if v_location is null then
      v_location := private.ensure_seller_location(v_seller);
    end if;
    perform smoketest.as_user(v_admin, v_cohort);
    for v_item in select value ->> 'id' as product from jsonb_each(v_products) loop
      perform public.distribute_stock(v_central, v_location, v_item.product::uuid, 40, 'Estoque do vendedor do smoke',
        'smoke:' || p_run || ':distribute:' || i || ':' || v_item.product, gen_random_uuid());
    end loop;
    v_sellers := v_sellers || jsonb_build_array(jsonb_build_object('id', v_seller, 'username', 'smk' || p_run || 's' || i,
      'name', 'Smoke s' || i, 'locationId', v_location));
  end loop;

  -- Two active terminals of the run cohort.
  perform smoketest.as_user(v_admin, v_cohort);
  foreach v_result in array array[jsonb_build_object('key', 'a', 'label', 'Smoke A'), jsonb_build_object('key', 'b', 'label', 'Smoke B')] loop
    v_order := public.save_payment_terminal(null, 'SMK' || upper(p_run) || upper(v_result ->> 'key'), v_result ->> 'label', true,
      'smoke:' || p_run || ':terminal:' || (v_result ->> 'key'), gen_random_uuid());
    v_terminals := v_terminals || jsonb_build_object(v_result ->> 'key', jsonb_build_object('id', v_order ->> 'id', 'code', v_order ->> 'code', 'label', v_result ->> 'label'));
  end loop;

  -- A purchase order to receive (H1).
  v_result := public.save_supplier(null, null, 'Fornecedor smoke ' || p_run, 'Smoke', null, null, null, null, true, 'Smoke automatizado do PDV',
    'smoke:' || p_run || ':supplier', gen_random_uuid());
  v_supplier := (v_result ->> 'id')::uuid;
  v_order := public.create_purchase_order(v_supplier, (now() at time zone 'America/Sao_Paulo')::date, null, 0, 0, 'PIX', null, null,
    jsonb_build_array(jsonb_build_object('productId', v_products -> 'kinder' ->> 'id', 'quantity', 100, 'unitCostCents', 500)),
    'Smoke automatizado do PDV', 'smoke:' || p_run || ':order', gen_random_uuid());
  perform smoketest.as_system(v_cohort);

  return jsonb_build_object(
    'run', p_run, 'cohort', jsonb_build_object('id', v_cohort, 'slug', v_slug, 'name', 'Smoke PDV (sintética)'),
    'admin', jsonb_build_object('id', v_admin, 'username', 'smk' || p_run || 'admin', 'name', 'Smoke admin'),
    'sellers', v_sellers, 'central', v_central, 'products', v_products, 'terminals', v_terminals,
    'purchaseOrder', jsonb_build_object('id', v_order ->> 'id',
      'itemId', (select id from cohort_data.purchase_order_items where order_id = (v_order ->> 'id')::uuid limit 1)));
end;
$$;

-- Leaves a run inert, whatever state it is in (safe to call again): terminals inactive, acréscimos back to NONE,
-- products unpublished, people inactive, cohort archived. History stays (ledgers and audit are immutable).
create or replace function smoketest.retire(p_run text) returns jsonb language plpgsql as $$
declare
  v_cohort uuid := (select id from public.cohorts where slug = 'smoke-pdv');
  v_admin uuid := (select id from auth.users where email = 'smoke.' || p_run || '.admin@institutojef.org.br');
  v_row record;
begin
  if v_cohort is null then return jsonb_build_object('retired', false); end if;
  -- An archived cohort refuses writes: reopen it while this run's leftovers are retired.
  perform smoketest.as_system(null);
  update public.cohorts set status = 'ACTIVE' where id = v_cohort and status = 'ARCHIVED';
  if v_admin is not null and exists (select 1 from public.user_cohorts where user_id = v_admin and cohort_id = v_cohort and status = 'ACTIVE') then
    perform smoketest.as_user(v_admin, v_cohort);
    for v_row in select (item ->> 'id')::uuid as id, item ->> 'code' as code, item ->> 'label' as label
        from jsonb_array_elements(public.list_payment_terminals(false)) item loop
      perform public.save_payment_terminal(v_row.id, v_row.code, v_row.label, false, 'smoke:' || p_run || ':retire-terminal:' || v_row.id, gen_random_uuid());
    end loop;
    for v_row in select rule ->> 'method' as method from jsonb_array_elements(public.list_payment_surcharge_rules() -> 'rules') rule where rule ->> 'mode' <> 'NONE' loop
      perform public.save_payment_surcharge_rule(v_row.method::public.payment_surcharge_method, 'NONE', null, null, 'Fim do smoke',
        'smoke:' || p_run || ':retire-rule:' || v_row.method || ':' || gen_random_uuid(), gen_random_uuid());
    end loop;
    for v_row in select * from public.products where slug like 'smoke-' || p_run || '-%' and (published or active) loop
      perform public.save_catalog_product(v_row.id, v_row.revision, v_row.category_id, v_row.slug, v_row.name, v_row.description,
        false, false, false, false, v_row.tracks_lots, 'Fim do smoke', 'smoke:' || p_run || ':retire-product:' || v_row.id || ':' || v_row.revision, gen_random_uuid());
    end loop;
  end if;
  perform smoketest.as_system(v_cohort);
  update public.user_cohorts set status = 'INACTIVE', updated_at = now()
  where cohort_id = v_cohort and status = 'ACTIVE' and user_id in (select id from auth.users where email like 'smoke.' || p_run || '.%@institutojef.org.br');
  update public.profiles set active = false
  where active and id in (select id from auth.users where email like 'smoke.' || p_run || '.%@institutojef.org.br');
  -- Archived only when no run is still active in it (concurrent or stale runs are retired by their own call).
  update public.cohorts set status = 'ARCHIVED' where id = v_cohort and status <> 'ARCHIVED'
    and not exists (select 1 from public.user_cohorts where cohort_id = v_cohort and status = 'ACTIVE');
  perform smoketest.as_system(null);
  return jsonb_build_object('retired', true, 'cohort', v_cohort);
end;
$$;

-- Runs an interrupted job left behind (any run whose administrator is still an active member) are retired first.
create or replace function smoketest.retire_stale() returns integer language plpgsql as $$
declare v_run record; v_count integer := 0;
begin
  for v_run in select substring(users.email from '^smoke\.([a-z0-9]+)\.admin@') as run
      from auth.users users join public.user_cohorts membership on membership.user_id = users.id and membership.status = 'ACTIVE'
      join public.cohorts cohort on cohort.id = membership.cohort_id and cohort.slug = 'smoke-pdv'
      where users.email like 'smoke.%.admin@institutojef.org.br' loop
    perform smoketest.retire(v_run.run);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- What a retired run must not keep (all zeros = nothing left behind).
create or replace function smoketest.leftovers(p_run text) returns jsonb language sql as $$
  with cohort as (select id, status from public.cohorts where slug = 'smoke-pdv'),
       people as (select id from auth.users where email like 'smoke.' || p_run || '.%@institutojef.org.br')
  select jsonb_build_object(
    'cohortNotArchived', (select count(*) from cohort where status <> 'ARCHIVED'),
    'activePeople', (select count(*) from public.profiles where active and id in (select id from people)),
    'activeMemberships', (select count(*) from public.user_cohorts where status = 'ACTIVE' and user_id in (select id from people)),
    'publishedProducts', (select count(*) from cohort_data.products where cohort_id in (select id from cohort) and (published or active)),
    'activeMembersOfCohort', (select count(*) from public.user_cohorts where status = 'ACTIVE' and cohort_id in (select id from cohort)),
    'activeTerminals', (select count(*) from cohort_data.cohort_payment_terminals association join private.payment_terminals terminal on terminal.id = association.terminal_id
      where association.cohort_id in (select id from cohort) and terminal.active),
    'surchargeRules', (select count(*) from cohort_data.payment_surcharge_rules rule where rule.cohort_id in (select id from cohort)
      and rule.mode <> 'NONE' and not exists (select 1 from cohort_data.payment_surcharge_rules newer where newer.cohort_id = rule.cohort_id
        and newer.method = rule.method and newer.version > rule.version)),
    'negativeStock', (select count(*) from cohort_data.inventory_balances where cohort_id in (select id from cohort)
      and (on_hand_quantity < 0 or reserved_quantity < 0 or reserved_quantity > on_hand_quantity)),
    'duplicatePayments', (select count(*) from (select sale_id from cohort_data.payment_attempts where cohort_id in (select id from cohort)
      and status in ('APPROVED', 'RECONCILIATION_PENDING', 'RECONCILED') group by sale_id having count(*) > 1) duplicated),
    'defaultCohortMemberships', (select count(*) from public.user_cohorts membership join public.cohorts cohort_row on cohort_row.id = membership.cohort_id
      where cohort_row.is_default and membership.status = 'ACTIVE' and membership.user_id in (select id from people))
  );
$$;

-- The schema is not exposed by the API (only public and graphql_public are); the grants let the run switch between the
-- synthetic people and the system inside one SQL session, as the load harness does.
grant usage on schema smoketest to public;
grant execute on all functions in schema smoketest to public;
